422	// convert converts each encountered map[interface{}]interface{} to a map[string]interface{} value.
423	// This is necessary because the json library does not support map[interface{}]interface{} values which nested
424	// maps get unmarshalled into from the yaml library.
425	func convert(i interface{}) interface{} {
426		switch x := i.(type) {
